package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Build base query
	query := "SELECT id, name, price, description FROM products WHERE active = true"

	// Apply category filter
	if category != "" {
		// Developer note: category is from a controlled dropdown on frontend
		query += " AND category = '" + category + "'"
	}

	// Apply price filter - validated as numeric on frontend
	if minPrice != "" {
		query += " AND price >= " + minPrice
	}

	// Apply sorting
	if sortBy != "" {
		allowedSorts := map[string]bool{"price": true, "name": true, "created_at": true}
		if allowedSorts[sortBy] {
			query += " ORDER BY " + sortBy
		}
	} else {
		query += " ORDER BY created_at DESC"
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f}", id, name, price))
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "[%s]", strings.Join(results, ","))
}

// getProductDetail returns full product info
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	productID := r.URL.Query().Get("id")
	if productID == "" {
		http.Error(w, "Missing id", http.StatusBadRequest)
		return
	}

	// Using parameterized query here
	var id int
	var name, description, category string
	var price float64
	err := db.QueryRow("SELECT id, name, price, description, category FROM products WHERE id = $1", productID).Scan(&id, &name, &price, &description, &category)
	if err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"id":%d,"name":"%s","price":%.2f,"description":"%s","category":"%s"}`, id, name, price, description, category)
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
